import fs from 'fs';
import path from 'path';
// Импортируем ваши реальные данные
import priceData from './src/data/priceData.js'; 

function generateCSV() {
  // Заголовки колонок для Excel (добавляем BOM-маркер для поддержки русской кириллицы в Excel)
  let csvContent = '\uFEFFКатегория;Наименование работ;Ед. измерения;Цена от, руб\n';

  // Перебираем все категории и строки данных
  Object.keys(priceData).forEach(category => {
    const formattedCategory = category.charAt(0).toUpperCase() + category.slice(1);
    
    priceData[category].forEach(row => {
      // Экранируем кавычки, если они есть в названиях (например, «Грильято»)
      const name = row.name.replace(/"/g, '""');
      csvContent += `"${formattedCategory}";"${name}";"${row.unit}";${row.price}\n`;
    });
  });

  // Определяем путь к папке public/files
  const dirPath = path.join(process.cwd(), 'public', 'files');
  
  // Если папок public/files еще нет — создаем их автоматически
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true });
  }

  // Записываем готовый файл
  fs.writeFileSync(path.join(dirPath, 'price-list.csv'), csvContent, 'utf-8');
  console.log('✅ Файл price-list.csv успешно сгенерирован в public/files/');
}

generateCSV();
